# واژه‌نامهٔ دوزبانه. link: (نوع صفحه، نامک) برای پیوند «بیشتر»
FA_ORDER = 'ءآاأبپتثجچحخدذرزژسشصضطظعغفقکگلمنوهیيكئ'
def sort_key(t, lang):
    if lang == 'en': return t['en'].lower()
    return [FA_ORDER.index(c) if c in FA_ORDER else 100 + ord(c) for c in t['fa'].replace('‌', '').replace(' ', '')]
def initial(t, lang):
    if lang == 'en':
        c = t['en'][0].upper(); return c if c.isalpha() else '#'
    c = t['fa'][0]
    if c == 'آ': return 'ا'
    return c if c in FA_ORDER else 'A–Z'

def T(id, fa, en, dfa, den, link=None): return dict(id=id, fa=fa, en=en, dfa=dfa, den=den, link=link)

